#include <bits/stdc++.h>
using namespace std;

static int totalA, totalB, n, k;
static const long long MOD = 1000000007;
static long long choose[100][100];
static unordered_map<int, pair<int, long long>> states;
static queue<int> q;

struct Pair {
    int depth;
    long long waysCount;
    Pair(int d, long long w) : depth(d), waysCount(w) {}
};

void processState(int state);
void updateState(int i, int j, int side, int prevState, long long waysEdge);
void prepareChoose();

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> k;
    totalA = 0;
    totalB = 0;
    for (int i = 0; i < n; i++) {
        int val; cin >> val;
        if (val == 50) totalA++;
        else totalB++;
    }
    prepareChoose();
    int startState = 1000000 + 100 * totalA + totalB;
    q.push(startState);
    states[startState] = {0, 1};
    while (!q.empty()) {
        processState(q.front());
        q.pop();
    }
    if (states.count(0))
        cout << states[0].first << "\n" << states[0].second << "\n";
    else
        cout << -1 << "\n0\n";
    return 0;
}

void processState(int state) {
    int boatSide = state / 1000000;
    int aCount = (state % 1000000) / 100;
    int bCount = state % 100;
    if (boatSide > 0) {
        for (int i = aCount; i >= 0 && 50 * (aCount - i) <= k; i--) {
            for (int j = bCount; j >= 0 && 50 * (aCount - i) + 100 * (bCount - j) <= k; j--) {
                if (i != aCount || j != bCount)
                    updateState(i, j, boatSide, state, choose[aCount][i] * choose[bCount][j] % MOD);
            }
        }
    } else {
        for (int i = aCount; i <= totalA && 50 * (i - aCount) <= k; i++) {
            for (int j = bCount; j <= totalB && 50 * (i - aCount) + 100 * (j - bCount) <= k; j++) {
                if (i != aCount || j != bCount)
                    updateState(i, j, boatSide, state, choose[totalA - aCount][i - aCount] * choose[totalB - bCount][j - bCount] % MOD);
            }
        }
    }
}

void updateState(int i, int j, int side, int prevState, long long waysEdge) {
    int newState = 1000000 * (1 - side) + i * 100 + j;
    int newDepth = states[prevState].first + 1;
    if (!states.count(newState)) {
        states[newState] = {newDepth, 0};
        q.push(newState);
    }
    if (states[newState].first == newDepth)
        states[newState].second = (states[newState].second + states[prevState].second * waysEdge % MOD) % MOD;
}

void prepareChoose() {
    for (int i = 0; i < 100; i++) choose[i][0] = 1;
    for (int i = 1; i < 100; i++) {
        for (int j = 1; j <= i; j++) {
            choose[i][j] = (choose[i - 1][j - 1] + choose[i - 1][j]) % MOD;
        }
    }
}

